package previewsetup

import (
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"

	"sigs.k8s.io/yaml"
)

// The files every recipe writes, relative to the output directory.
const (
	AnswersFile   = "answers.yaml"
	ValuesFile    = "patchy-previews.values.yaml"
	NextStepsFile = "NEXT-STEPS.md"
)

// ChartRef is the patchy chart NEXT-STEPS.md upgrades the release from.
const ChartRef = "oci://ghcr.io/devthenet-labs/patchy/charts/patchy"

// File is one generated file. Secret files are never diffed or printed.
type File struct {
	Path   string // slash-separated, relative to the output directory
	Data   []byte
	Secret bool
}

// ErrRecipeNotReady reports an edge whose recipe has not landed yet.
var ErrRecipeNotReady = errors.New("this recipe is not available yet")

// recipe renders an edge's own files and values over the common ones.
type recipe func(a Answers, v values) ([]File, error)

// recipes are the edges with a recipe. cloudflare-tunnel follows in a
// change of its own.
var recipes = map[Edge]recipe{
	EdgeExisting:   existingRecipe,
	EdgeGatewayTLS: gatewayTLSRecipe,
	EdgeTailscale:  tailscaleRecipe,
}

// Ready reports whether edge has a recipe in this CLI.
func Ready(edge Edge) bool {
	_, ok := recipes[edge]
	return ok
}

// semverPattern is a release version, which names a chart version too.
var semverPattern = regexp.MustCompile(`^v?([0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?)$`)

// Plan renders the files for a, with s's secrets, as CLI version version
// writes them: byte-stable for the same three, sorted by path. a must be
// normalized, complete (no Missing) and valid.
func Plan(a Answers, s Secrets, version string) ([]File, error) {
	if m := a.Missing(); len(m) > 0 {
		return nil, fmt.Errorf("unanswered: %s", strings.Join(m, ", "))
	}
	if err := a.Validate(); err != nil {
		return nil, err
	}
	r, ok := recipes[a.Edge]
	if !ok {
		return nil, fmt.Errorf("--edge %s: %w (ready: %s)", a.Edge, ErrRecipeNotReady, strings.Join(readyEdges(), ", "))
	}
	a.CLIVersion = version
	v := commonValues(a)
	files, err := r(a, v)
	if err != nil {
		return nil, err
	}
	vals, err := v.render(a)
	if err != nil {
		return nil, err
	}
	ans, err := MarshalAnswers(a)
	if err != nil {
		return nil, err
	}
	secrets, err := secretFiles(a, s)
	if err != nil {
		return nil, err
	}
	next, err := renderNextSteps(a, files, secrets)
	if err != nil {
		return nil, err
	}
	files = append(files, File{Path: ValuesFile, Data: vals}, File{Path: AnswersFile, Data: ans},
		File{Path: NextStepsFile, Data: next})
	files = append(files, secrets...)
	slices.SortFunc(files, func(x, y File) int { return strings.Compare(x.Path, y.Path) })
	return files, nil
}

func readyEdges() []string {
	var out []string
	for _, e := range Edges() {
		if Ready(Edge(e)) {
			out = append(out, e)
		}
	}
	return out
}

// values is the patchy values tree a plan renders, nested maps marshalled
// with sorted keys.
type values map[string]any

// at returns the map at path, creating each level.
func (v values) at(path ...string) map[string]any {
	m := map[string]any(v)
	for _, k := range path {
		next, ok := m[k].(map[string]any)
		if !ok {
			next = map[string]any{}
			m[k] = next
		}
		m = next
	}
	return m
}

// render marshals the values under a header saying how to layer them.
func (v values) render(a Answers) ([]byte, error) {
	body, err := yaml.Marshal(map[string]any(v))
	if err != nil {
		return nil, fmt.Errorf("render %s: %w", ValuesFile, err)
	}
	head := fmt.Sprintf("# Generated by `patchy setup previews` (patchy %s, edge %s).\n"+
		"# Layer it after your own values:\n"+
		"#   helm upgrade %s %s -n %s \\\n#     -f <your values> -f %s\n"+
		"# Change it by running the command again: it shows the difference before replacing this file.\n",
		a.CLIVersion, a.Edge, a.Release, ChartRef, a.Namespace, ValuesFile)
	return append([]byte(head), body...), nil
}

// commonValues are every recipe's values (design §4.3, "Common to every
// recipe"): previews on, the gateway alone serving them (no legacy slot
// Ingress, no placeholder ALB), node isolation, the preview-controller and
// the relay with its Dex client and viewers. No previewAuth.stage: the
// permit/require pair is the preview ALB's, inert in gateway mode.
func commonValues(a Answers) values {
	v := values{}
	p := v.at("preview")
	p["enabled"] = true
	p["hostSuffix"] = a.HostSuffix
	p["imageRegistry"] = a.Registry
	p["imagePathPrefix"] = a.ImagePathPrefix
	p["legacyIngress"] = false
	v.at("preview", "placeholder")["enabled"] = false
	nodeIsolationValues(a, v.at("preview", "nodeIsolation"))
	pc := v.at("previewController")
	pc["enabled"] = true
	v.at("previewController", "config")["apiServerCIDR"] = a.APIServerCIDR
	pa := v.at("previewAuth")
	pa["enabled"] = true
	pa["host"] = a.SignInHost
	dex := v.at("previewAuth", "dex")
	dex["issuerURL"] = a.Dex.Issuer
	dex["clientID"] = a.Dex.ClientID
	dex["existingSecret"] = RelayDexSecret
	dex["clientSecretKey"] = RelayDexSecretKey
	viewers := v.at("previewAuth", "viewers")
	viewers["teams"] = stringsOrEmpty(a.Viewers.Teams)
	viewers["users"] = stringsOrEmpty(a.Viewers.Users)
	v.at("previewAuth", "gateway")["enabled"] = true
	return v
}

// nodeIsolationValues fills preview.nodeIsolation. The file is layered
// after the operator's own values and Helm merges maps, so every key that
// picks the nodes is written, an EKS Auto Mode pair (and its legacy
// spellings) as "" when unanswered: one left in the operator's values
// would otherwise be merged with the selector and require labels no
// preview node carries. A selector map cannot be cleared that way;
// NEXT-STEPS.md says to remove it.
func nodeIsolationValues(a Answers, iso map[string]any) {
	eks := a.NodeIsolation.EKSAutoMode
	iso["eksAutoMode"] = map[string]any{"nodePool": eks.NodePool, "nodeClass": eks.NodeClass}
	iso["nodePool"] = ""
	iso["nodeClass"] = ""
	switch {
	case a.IsolationMode() == IsolationNone:
		iso["mode"] = IsolationNone
		iso["selector"] = map[string]any{}
		iso["taintKey"] = ""
	case eks != (EKSAutoMode{}):
		iso["mode"] = IsolationRequired
		iso["selector"] = map[string]any{}
		iso["taintKey"] = a.NodeIsolation.TaintKey
	default:
		iso["mode"] = IsolationRequired
		iso["selector"] = map[string]any{a.NodeIsolation.Label: a.NodeIsolation.LabelValue}
		iso["taintKey"] = a.NodeIsolation.TaintKey
	}
}

// stringsOrEmpty is s, or an empty list: the wizard's viewers are the
// whole list, replacing any in the operator's own values.
func stringsOrEmpty(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// GatewayService is the gateway's Service, what every edge routes to.
func (a Answers) GatewayService() string { return a.Fullname() + "-preview-gateway" }

// ChartVersion is the chart version a CLI version pins, "" for a build
// that is no release.
func ChartVersion(version string) string {
	if m := semverPattern.FindStringSubmatch(version); m != nil {
		return m[1]
	}
	return ""
}
